  @Finset.Nonempty.{u_1} α (@Inter.inter.{u_1} (Finset.{u_1} α) (@Finset.instInter.{u_1} α inst) s t) →
    Not (@Disjoint.{u_1} (Finset.{u_1} α) (@Finset.instPartialOrder.{u_1} α) (@Finset.instOrderBot.{u_1} α) s t)

