    (Finset.{u_1} ↥(@EmptyCollection.emptyCollection.{u_1} (Finset.{u_1} α) (@Finset.instEmptyCollection.{u_1} α)))
    (@Finset.attach.{u_1} α
      (@EmptyCollection.emptyCollection.{u_1} (Finset.{u_1} α) (@Finset.instEmptyCollection.{u_1} α)))
    (@EmptyCollection.emptyCollection.{u_1}
