        ↥(@EmptyCollection.emptyCollection.{u_1} (Finset.{u_1} α) (@Finset.instEmptyCollection.{u_1} α))))

∀ {α : Type u_1} (s t : Finset.{u_1} α) {p q : α → Prop} [inst : @DecidablePred.{u_1 + 1} α p]
  [inst_1 : @DecidablePred.{u_1 + 1} α q],
  @Disjoint.{u_1} (α → Prop) (@Pi.partialOrder.{u_1, 0} α (fun a => Prop) fun i => «Prop».partialOrder)
      (@Pi.instOrderBot.{u_1, 0} α (fun a => Prop) (fun i => «Prop».le) fun i =>
        @HeytingAlgebra.toOrderBot.{0} Prop «Prop».instHeytingAlgebra)
      p q →
    @Disjoint.{u_1} (Finset.{u_1} α) (@Finset.instPartialOrder.{u_1} α) (@Finset.instOrderBot.{u_1} α)
      (@Finset.filter.{u_1} α p inst s) (@Finset.filter.{u_1} α q inst_1 t)

∀ {α : Type u_1} [inst : DecidableEq.{u_1 + 1} α] {s t : Finset.{u_1} α} {a : α},
  a ∉ t →
    @Disjoint.{u_1} (Finset.{u_1} α) (@Finset.instPartialOrder.{u_1} α) (@Finset.instOrderBot.{u_1} α)
        (@Finset.erase.{u_1} α inst s a) t →
      @Disjoint.{u_1} (Finset.{u_1} α) (@Finset.instPartialOrder.{u_1} α) (@Finset.instOrderBot.{u_1} α) s t

∀ {α : Type u_1} [inst : DecidableEq.{u_1 + 1} α] {s t : Finset.{u_1} α} {a : α},
  a ∉ s →
    @Disjoint.{u_1} (Finset.{u_1} α) (@Finset.instPartialOrder.{u_1} α) (@Finset.instOrderBot.{u_1} α) s
        (@Finset.erase.{u_1} α inst t a) →
      @Disjoint.{u_1} (Finset.{u_1} α) (@Finset.instPartialOrder.{u_1} α) (@Finset.instOrderBot.{u_1} α) s t

∀ {α : Type u_1} [inst : DecidableEq.{u_1 + 1} α] {s t : Finset.{u_1} α},
  @Disjoint.{u_1} (Finset.{u_1} α) (@Finset.instPartialOrder.{u_1} α) (@Finset.instOrderBot.{u_1} α) s
