∀ {α : Type u_1} [inst : DecidableEq.{u_1 + 1} α] {a b : α} {s : Finset.{u_1} α} (ha : a ∉ s),
  @Ne.{u_1 + 1} α a b →
    @Eq.{u_1 + 1} (Finset.{u_1} α) (@Finset.erase.{u_1} α inst (@Finset.cons.{u_1} α a s ha) b)
      (@Finset.cons.{u_1} α a (@Finset.erase.{u_1} α inst s b) ⋯)

∀ {α : Type u_1} [inst : DecidableEq.{u_1 + 1} α] (a : α),
  @Set.InjOn.{u_1, u_1} (Finset.{u_1} α) (Finset.{u_1} α) (fun s => @Finset.erase.{u_1} α inst s a)
    (@Set.ofPred.{u_1} (Finset.{u_1} α) fun s =>
      @Membership.mem.{u_1, u_1} α (Finset.{u_1} α)
        (@SetLike.instMembership.{u_1, u_1} (Finset.{u_1} α) α (@Finset.instSetLike.{u_1} α)) s a)

∀ {α : Type u_1} [inst : DecidableEq.{u_1 + 1} α] {s : Finset.{u_1} α} {a b : α},
  @Ne.{u_1 + 1} α a b →
    @Membership.mem.{u_1, u_1} α (Finset.{u_1} α)
        (@SetLike.instMembership.{u_1, u_1} (Finset.{u_1} α) α (@Finset.instSetLike.{u_1} α)) s b →
      @Eq.{u_1 + 1} (Finset.{u_1} α)
        (@SDiff.sdiff.{u_1} (Finset.{u_1} α) (@Finset.instSDiff.{u_1} α inst) (@Finset.erase.{u_1} α inst s a)
          (@Finset.erase.{u_1} α inst s b))
        (@Singleton.singleton.{u_1, u_1} α (Finset.{u_1} α) (@Finset.instSingleton.{u_1} α) b)

∀ {α : Type u_1} [inst : DecidableEq.{u_1 + 1} α] {s t : Finset.{u_1} α} [inst_1 : (i : α) → Decidable (i ∉ t)],
  @Eq.{u_1 + 1} (Finset.{u_1} α) ({i ∈ s | i ∉ t})
    (@SDiff.sdiff.{u_1} (Finset.{u_1} α) (@Finset.instSDiff.{u_1} α inst) s t)

∀ {α : Type u_1} [inst : DecidableEq.{u_1 + 1} α] {ι : Type u_3} {s : Set.{u_3} ι} {f : ι → Finset.{u_1} α},
  Iff
    (@Set.PairwiseDisjoint.{u_1, u_3} (Finset.{u_1} α) ι (@Finset.instPartialOrder.{u_1} α)
      (@Finset.instOrderBot.{u_1} α) s f)
    (∀ ⦃i : ι⦄,
      @Membership.mem.{u_3, u_3} ι (Set.{u_3} ι) (@Set.instMembership.{u_3} ι) s i →
        ∀ ⦃j : ι⦄,
          @Membership.mem.{u_3, u_3} ι (Set.{u_3} ι) (@Set.instMembership.{u_3} ι) s j →
            @Finset.Nonempty.{u_1} α
                (@Inter.inter.{u_1} (Finset.{u_1} α) (@Finset.instInter.{u_1} α inst) (f i) (f j)) →
              @Eq.{u_3 + 1} ι i j)

∀ {α : Type u_1} [inst : DecidableEq.{u_1 + 1} α] {s t : Finset.{u_1} α},
  @Disjoint.{u_1} (Finset.{u_1} α) (@Finset.instPartialOrder.{u_1} α) (@Finset.instOrderBot.{u_1} α)
    (@SDiff.sdiff.{u_1} (Finset.{u_1} α) (@Finset.instSDiff.{u_1} α inst) t s) s

∀ {α : Type u_1} [inst : DecidableEq.{u_1 + 1} α] (s₁ s₂ : Finset.{u_1} α),
  @Eq.{u_1 + 1} (Finset.{u_1} α) (@SDiff.sdiff.{u_1} (Finset.{u_1} α) (@Finset.instSDiff.{u_1} α inst) s₁ s₂)
    ({x ∈ s₁ | x ∉ s₂})

∀ {α : Type u_1} [inst : DecidableEq.{u_1 + 1} α] {s : Finset.{u_1} α} {a : α},
  @Membership.mem.{u_1, u_1} α (Finset.{u_1} α)
      (@SetLike.instMembership.{u_1, u_1} (Finset.{u_1} α) α (@Finset.instSetLike.{u_1} α)) s a →
    @Eq.{u_1 + 1} (Finset.{u_1} α)
      (@SDiff.sdiff.{u_1} (Finset.{u_1} α) (@Finset.instSDiff.{u_1} α inst) s (@Finset.erase.{u_1} α inst s a))
      (@Singleton.singleton.{u_1, u_1} α (Finset.{u_1} α) (@Finset.instSingleton.{u_1} α) a)

∀ {α : Type u_1} [inst : DecidableEq.{u_1 + 1} α] (s : List.{u_1} α) (p : α → Bool),
  @Eq.{u_1 + 1} (Finset.{u_1} α) (@List.toFinset.{u_1} α inst (@List.filter.{u_1} α p s))
    ({x ∈ @List.toFinset.{u_1} α inst s | @Eq.{1} Bool (p x) Bool.true})

∀ {α : Type u_1} [inst : DecidableEq.{u_1 + 1} α] {s : Multiset.{u_1} α},
  @Ne.{u_1 + 1} (Multiset.{u_1} α) s
